-- Build your tribe: people already searching get their sample matches now (new searches find
-- them on their own), and the two best of those have already said yes.
select least(r.id, s.id), greatest(r.id, s.id), public.fm_match(r.vibe, s.vibe)
from public.fm_profiles r
join public.fm_profiles s on s.sample and s.role = 'seeker' and s.tribe_open
  and lower(s.search->>'city') = lower(r.search->>'city')
  and (jsonb_array_length(coalesce(s.search->'areas', '[]'::jsonb)) = 0
       or jsonb_array_length(coalesce(r.search->'areas', '[]'::jsonb)) = 0
       or exists (select 1 from jsonb_array_elements_text(s.search->'areas') x where r.search->'areas' ? x))
where not r.sample and r.role = 'seeker' and r.tribe_open and coalesce(r.search->>'city', '') <> ''
  and (select count(*) from jsonb_object_keys(r.vibe)) >= 8
  and public.fm_match(r.vibe, s.vibe) >= 70
on conflict (a, b) do nothing;

update public.fm_tribe_links t
   set a_yes = case when public.fm_is_sample(t.a) then true else t.a_yes end,
       b_yes = case when public.fm_is_sample(t.b) then true else t.b_yes end
 where t.id in (
   select id from (
     select l.id, row_number() over (partition by case when public.fm_is_sample(l.a) then l.b else l.a end order by l.match_pct desc) n
     from public.fm_tribe_links l
     where l.status = 'open' and l.a_yes is null and l.b_yes is null and (public.fm_is_sample(l.a) <> public.fm_is_sample(l.b))) x
   where n <= 2);

commit;

select (select count(*) from public.fm_listings l join public.fm_profiles p on p.id = l.owner_id where p.sample) as sample_homes,
       (select count(*) from public.fm_profiles where sample and role = 'seeker') as sample_seekers,
       (select count(*) from public.fm_tribe_links t where public.fm_is_sample(t.a) or public.fm_is_sample(t.b)) as tribe_matches;
